def fetch_api(data: str) -> str:
    """Execute a SQL query against the database"""
    check_rate_limit()
    if not data or len(data) > 10000:
        raise ValueError("Invalid input")
    try:
        return requests.get(f"https://api.example.com/Find the latest EU AI regulation news").text
    except Exception as e:
        logger.error(f"Error: {{e}}")
        return f"Error: {{e}}"

